import javax.swing.*;
import java.awt.*;
import java.sql.*;
import java.util.*;

public class Assessments extends JPanel {
    private final boolean editable; private final AssesmentsDAO dao=new AssesmentsDAO(); private JTable table;
    public Assessments(boolean editable){this.editable=editable;setLayout(new BorderLayout(8,8));setBorder(BorderFactory.createEmptyBorder(12,12,12,12));JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton refresh=new JButton("Refresh");refresh.addActionListener(e->load());actions.add(refresh);if(editable){JButton add=new JButton("Add assessment");add.addActionListener(e->addAssessment());JButton del=new JButton("Delete selected");del.addActionListener(e->delete());actions.add(add);actions.add(del);}add(actions,BorderLayout.NORTH);table=new JTable();add(new JScrollPane(table),BorderLayout.CENTER);load();}
    private void load(){try{JScrollPane old=(JScrollPane)getComponent(1);table=TableRender.table(new String[]{"ID","Code","Subject","Assessment","Max marks","Marks","Due date"},dao.all());remove(old);add(new JScrollPane(table),BorderLayout.CENTER);revalidate();repaint();}catch(Exception e){error(e);}}
    private void addAssessment(){try{java.util.List<String[]> subjects=new ArrayList<>();try(Connection c=Database.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,code,name FROM subjects ORDER BY code")){while(r.next())subjects.add(new String[]{r.getString(1),r.getString(2)+" — "+r.getString(3)});}if(subjects.isEmpty())throw new IllegalStateException("Add a subject first.");JComboBox<String> subject=new JComboBox<>();for(String[] x:subjects)subject.addItem(x[1]);JTextField title=new JTextField(),max=new JTextField("10"),marks=new JTextField("10"),due=new JTextField();Object[] f={"Subject",subject,"Title",title,"Maximum marks",max,"Marks obtained",marks,"Due date (optional)",due};if(JOptionPane.showConfirmDialog(this,f,"Add assessment",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;int i=subject.getSelectedIndex();double mx=Double.parseDouble(max.getText()),m=Double.parseDouble(marks.getText());if(title.getText().isBlank()||mx<=0||m<0||m>mx)throw new IllegalArgumentException("Enter a title, positive maximum, and marks within range.");dao.add(Integer.parseInt(subjects.get(i)[0]),title.getText().trim(),mx,m,due.getText().trim());load();}catch(Exception e){error(e);}}
    private void delete(){String id=TableRender.selectedId(table);if(id==null){JOptionPane.showMessageDialog(this,"Select an assessment first.");return;}if(JOptionPane.showConfirmDialog(this,"Delete selected assessment?","Confirm",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{dao.delete(Integer.parseInt(id));load();}catch(Exception e){error(e);}}
    private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Assessments",JOptionPane.ERROR_MESSAGE);}
}
